import type { PriceListCode } from "@/lib/portal/priceLists";

export type BundledPortalPriceSheet = {
  code: PriceListCode;
  fileName: string;
  contentBase64: string;
};

export const bundledPortalPriceSheets = {
  P6: {
    code: "P6",
    fileName: "alnpricing_2026_P6.pdf",
    contentBase64: "",
  },
  G6: {
    code: "G6",
    fileName: "alnpricing_2026_G6.pdf",
    contentBase64: "",
  },
  A6: {
    code: "A6",
    fileName: "alnpricing_2026_A6.pdf",
    contentBase64: "",
  },
  B5: {
    code: "B5",
    fileName: "alnpricing_2026_B5.pdf",
    contentBase64: "",
  },
  S5: {
    code: "S5",
    fileName: "alnpricing_2026_S5.pdf",
    contentBase64: "",
  },
  VD: {
    code: "VD",
    fileName: "alnpricing_2026_VD.pdf",
    contentBase64: "",
  },
} satisfies Record<PriceListCode, BundledPortalPriceSheet>;

export function getBundledPortalPriceSheet(code: string) {
  return bundledPortalPriceSheets[code.trim().toUpperCase() as PriceListCode];
}
